def setting(name, default=''):
    if name in os.environ:
        return os.environ[name].strip()
    try:
        return str(st.secrets.get(name, default)).strip()
    except FileNotFoundError:
        return default


def ids(name):
    return frozenset(x.strip() for x in setting(name).split(',') if x.strip())


def demo_mode():
    return setting('ACHATS_MODE', 'production' if setting('CLICKUP_OAUTH_CLIENT_ID') else 'demo').lower() == 'demo'

# Relais OAuth repris de Soleol Relances V88 (état et preuve par session).
import secrets
import threading
import time

class RelaisOAuth:
    def __init__(self):
        self.verrou = threading.Lock()
        self.demandes = {}

    def nettoyer(self):
        maintenant = time.monotonic()
        for identifiant in list(self.demandes):
            if self.demandes[identifiant]['expiration'] <= maintenant:
                del self.demandes[identifiant]

    def creer(self):
        with self.verrou:
            self.nettoyer()
            if len(self.demandes) >= 1000:
                raise ValueError('Trop de connexions en cours. Réessayez plus tard.')
            etat, preuve = secrets.token_urlsafe(32), secrets.token_urlsafe(32)
            self.demandes[etat] = {'preuve': preuve, 'expiration': time.monotonic()+600, 'statut': 'attente'}
            return etat, preuve

    def reserver(self, etat):
        with self.verrou:
            self.nettoyer()
            demande = self.demandes.get(etat)
            if not demande or demande['statut'] != 'attente':
                return False
            demande['statut'] = 'traitement'
            return True

    def terminer(self, etat, resultat):
        with self.verrou:
            self.nettoyer()
            demande = self.demandes.get(etat)
            if demande and demande['statut'] == 'traitement':
                demande.update(statut='termine', resultat=resultat)
                return True
            return False

    def recuperer(self, etat, preuve):
        with self.verrou:
            self.nettoyer()
            demande = self.demandes.get(etat)
            if not demande or not secrets.compare_digest(demande['preuve'], preuve):
                return {'erreur': 'Connexion expirée. Recommencez la connexion.'}
            if demande['statut'] != 'termine':
                return None
            del self.demandes[etat]
            return demande['resultat']

    def annuler(self, etat, preuve):
        with self.verrou:
            self.nettoyer()
            demande = self.demandes.get(etat)
            if demande and secrets.compare_digest(demande['preuve'], preuve):
                del self.demandes[etat]

# Connexion personnelle ClickUp, adaptée du relais OAuth de Relances V88.
import json
import ssl
import time
from urllib.parse import urlencode, urlparse
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError
import streamlit as st

class AuthError(ValueError):
    pass

@st.cache_resource
def relay():
    return RelaisOAuth()

def api(path, token=None, payload=None):
    headers = {'Accept': 'application/json'}
    if token:
        headers['Authorization'] = 'Bearer ' + token
    data = None
    if payload is not None:
        headers['Content-Type'] = 'application/json'
        data = json.dumps(payload).encode()
    req = Request('https://api.clickup.com/api/v2/' + path, headers=headers, data=data)
    try:
        with urlopen(req, timeout=25, context=ssl.create_default_context()) as r:
            return json.load(r)
    except (HTTPError, URLError, TimeoutError, OSError, ValueError) as exc:
        raise AuthError('ClickUp ne répond pas ou la connexion a expiré. Réessayez ou reconnectez-vous.') from exc

def configuration():
    cfg = {k: setting('CLICKUP_OAUTH_' + k.upper()) for k in ('client_id','client_secret','redirect_uri')}
    u = urlparse(cfg['redirect_uri'])
    valid = u.scheme == 'https' or (u.scheme == 'http' and u.hostname in ('localhost','127.0.0.1'))
    if not all(cfg.values()) or not valid or not u.netloc or u.query or u.fragment or u.username:
        return None
    return cfg

def identity(token):
    user = api('user', token).get('user') or {}
    if not user.get('id') or not user.get('username'):
        raise AuthError('Identité ClickUp non confirmée.')
    allowed = ids('CLICKUP_ALLOWED_WORKSPACE_IDS')
    if not allowed:
        raise AuthError('L’administrateur doit configurer les espaces ClickUp autorisés.')
    teams = api('team', token).get('teams', [])
    if not allowed.intersection(str(t['id']) for t in teams):
        raise AuthError('Autorisez l’espace ClickUp de Soleol lors de la connexion. Cet espace est requis.')
    return {'id': str(user['id']), 'name': str(user['username']), 'email': str(user.get('email') or '')}

def callback():
    if not any(k in st.query_params for k in ('code','state','error')):
        if st.session_state.get('callback_done'):
            st.info('Retournez dans votre onglet initial pour utiliser la plateforme.')
            st.stop()
        return
    params={k:st.query_params.get_all(k) for k in ('code','state','error')}
    st.query_params.clear()
    cfg=configuration()
    if not cfg or len(params['state'])!=1 or (not params['error'] and len(params['code'])!=1) or not relay().reserver(params['state'][0]):
        st.error('Connexion invalide ou expirée. Recommencez depuis l’onglet initial.')
        st.stop()
    result={'error':'Autorisation ClickUp refusée.'}
    if not params['error']:
        try:
            response=api('oauth/token',payload={k:cfg[k] for k in ('client_id','client_secret')}|{'code':params['code'][0]})
            access_token=response.get('access_token')
            if not isinstance(access_token,str) or not access_token or any(c.isspace() for c in access_token):
                raise AuthError('Connexion ClickUp non confirmée. Recommencez.')
            result={'token':access_token,'user':identity(access_token),'created':time.time(),'verified':time.time()}
        except AuthError as exc:
            result={'error':str(exc)}
    delivered=relay().terminer(params['state'][0],result)
    st.session_state['callback_done']=True
    if delivered and result.get('token'):
        st.success('Compte connecté. Fermez cet onglet et revenez dans la fenêtre initiale.')
    else:
        st.error(result.get('error','Connexion expirée. Recommencez depuis l’onglet initial.'))
    st.stop()


def current_user(force=False):
    account = st.session_state.get('account')
    if not account:
        return st.session_state.get('demo_user') if demo_mode() and not configuration() else None
    if time.time() - account['created'] > 8 * 3600:
        st.session_state.pop('account', None)
        raise AuthError('Session expirée après 8 heures. Reconnectez-vous.')
    if force or time.time() - account['verified'] > 300:
        try:
            user = identity(account['token'])
            if user['id'] != account['user']['id']:
                raise AuthError('Le compte a changé. Reconnectez-vous.')
            account.update(user=user, verified=time.time())
        except AuthError:
            st.session_state.pop('account', None)
            raise
    return account['user']

def buyer_ids():
    if demo_mode():
        account=st.session_state.get('account')
        return frozenset({str(account['user']['id'])}) if account else frozenset({'demo-preview'})
    return ids('ACHATS_BUYER_IDS')

def logout():
    pending = st.session_state.get('pending_auth')
    if pending:
        relay().annuler(*pending)
    st.session_state.clear()
    st.rerun()

