def today():
    return datetime.now(ZoneInfo('Europe/Zurich')).date()


def stamp():
    return datetime.now(ZoneInfo('Europe/Zurich')).isoformat(timespec='seconds')


def nice(value):
    return date.fromisoformat(value).strftime('%d.%m.%Y') if value else 'À préciser'


def normalize_prs(value):
    return re.sub(r'[\s-]', '', value).upper()


def valid_prs(value):
    return bool(re.fullmatch(r'PRS\d{3,20}', value))


PRS_FIELD_ID = '0fcbaa3f-fc7e-4d9d-a0d7-9d6496a7f5ac'
COST_FILE_FIELD_ID = '926eb7f5-f2ab-45e7-97c1-5ac5349345c8'
COST_FILE_BLOCK = 'Commande bloquée : aucun lien valide vers le fichier coûts dans le projet ClickUp. Demandez le fichier coûts à la direction et faites renseigner le lien avant de commander.'


def cost_file_link(task):
    for field in task.get('custom_fields', []):
        if str(field.get('id')) == COST_FILE_FIELD_ID:
            value=field.get('value')
            if not isinstance(value,str):
                return ''
            value=value.strip()
            try:
                url=urlparse(value)
                if url.scheme in ('http','https') and url.hostname and not url.username and not any(c.isspace() for c in value):
                    return value
            except ValueError:
                pass
            return ''
    return ''


PROJECT_WORKSPACE_ID = '9015136987'


def project_matches(task, prs, field_id=PRS_FIELD_ID):
    # Le nom de la tâche ne constitue jamais une correspondance PRS.
    for field in task.get('custom_fields', []):
        if str(field.get('id')) != field_id:
            continue
        value=field.get('value')
        if isinstance(value,bool) or value is None:
            return False
        if isinstance(value,float) and value.is_integer():
            value=int(value)
        candidate=normalize_prs(str(value))
        if candidate.isdigit():
            candidate='PRS'+candidate
        return candidate==normalize_prs(prs)
    return False


def list_tasks(list_id, token):
    if not str(list_id).isdigit():
        raise ValueError('Identifiant de liste ClickUp invalide.')
    for page in range(200):
        response = api(f'list/{list_id}/task?' + urlencode({'page':page, 'include_closed':'true', 'include_timl':'true'}), token)
        tasks = response.get('tasks', [])
        yield from tasks
        if response.get('last_page') is True or not tasks:
            return
    raise ValueError('Cette liste est trop volumineuse. Limitez la recherche aux listes de projets pertinentes.')


def find_projects(prs, token=None):
    prs=normalize_prs(prs)
    if not valid_prs(prs):
        raise ValueError('Renseignez un PRS suivi de chiffres, par exemple PRS260184.')
    if not token:
        if demo_mode() and not configuration():
            return [{'id':'demo-'+prs,'name':DEMO_PROJECTS[prs],'source':'demo','cost_file_url':'https://example.com/fichier-couts'}] if prs in DEMO_PROJECTS else []
        raise AuthError('Cliquez sur « Synchroniser mon ClickUp » avant de rechercher un projet.')
    # Même en aperçu, une recherche réelle exige un compte autorisé.
    identity(token)
    if PROJECT_WORKSPACE_ID not in ids('CLICKUP_ALLOWED_WORKSPACE_IDS'):
        raise AuthError('L’espace Soleol doit être autorisé dans CLICKUP_ALLOWED_WORKSPACE_IDS.')
    results={}
    for page in range(200):
        query={'page':page,'include_closed':'true','subtasks':'true',
               'custom_fields':json.dumps([{'field_id':PRS_FIELD_ID,'operator':'=','value':prs[3:]}])}
        # Le filtre serveur contient les chiffres ; la vérification locale exige
        # ensuite le PRS complet exact, en tolérant espaces, tirets et préfixe PRS.
        response=api(f'team/{PROJECT_WORKSPACE_ID}/task?'+urlencode(query),token)
        tasks=response.get('tasks',[])
        for task in tasks:
            if not task.get('archived') and project_matches(task,prs):
                task_id=str(task.get('id') or '')
                name=str(task.get('name') or '').strip()
                if task_id and name:
                    results[task_id]={'id':task_id,'name':name,'source':'clickup','has_cost_file':bool(cost_file_link(task))}
        if response.get('last_page') is True or not tasks:
            return list(results.values())
    raise ValueError('Trop de résultats ClickUp pour ce PRS. Vérifiez le numéro du projet.')


def event(user, message):
    return {'at':stamp(), 'actor':user['name'], 'message':message}


def validate_request(data):
    destination=data.get('destination','project')
    if destination not in ('project','stock530'):
        raise ValueError('Destination de la demande invalide.')
    if destination=='stock530':
        if data.get('prs') or data.get('project_task_id'):
            raise ValueError('Stock 530 ne doit pas être associé à un PRS.')
        data.update(project='Matériel commun pour le dépôt',cost_file=False,cost_file_url='')
    else:
        if data.get('cost_file') is not True:
            raise ValueError('Demandez le fichier coûts à la direction avant de commander.')
        if not valid_prs(data.get('prs','')) or not data.get('project_task_id') or not data.get('project'):
            raise ValueError('Recherchez le PRS dans ClickUp, puis validez le projet proposé.')
    for field in ['project','title','address']:
        if not str(data.get(field,'')).strip() or len(data[field]) > 500:
            raise ValueError('Renseignez le projet, l’objet et l’adresse de livraison (500 caractères maximum).')
    try:
        needed = date.fromisoformat(data['needed'])
    except (ValueError, KeyError, TypeError):
        raise ValueError('Date souhaitée invalide.') from None
    if needed < today():
        raise ValueError('La date souhaitée ne peut pas être dans le passé.')
    if data.get('priority') not in ('Normale','Urgente'):
        raise ValueError('Priorité invalide.')
    if len(str(data.get('notes',''))) > 5000:
        raise ValueError('Remarques : 5 000 caractères maximum.')
    clean = []
    for row in data.get('lines', []):
        label = str(row.get('designation') or '').strip()
        ref = str(row.get('reference') or '').strip()
        if not label and not ref and row.get('quantity') in (None,'',0):
            continue
        try:
            q = float(row.get('quantity'))
        except (ValueError,TypeError):
            raise ValueError('Renseignez une quantité positive pour chaque article.') from None
        if not label or not math.isfinite(q) or q <= 0 or q > 1e9:
            raise ValueError('Chaque article doit avoir une désignation et une quantité positive.')
        if len(label)>500 or len(ref)>500 or row.get('unit') not in ('pce','m','lot','kg','m²','rouleau'):
            raise ValueError('Article invalide : vérifiez la référence, la désignation et l’unité.')
        clean.append({'reference':ref,'designation':label,'quantity':q,'unit':row['unit']})
    if not 1 <= len(clean) <= 100:
        raise ValueError('Ajoutez entre 1 et 100 articles.')
    data['lines'] = clean
    return data


class Conflict(ValueError):
    pass


class OrderStore:
    """PostgreSQL partagé en production ; mémoire de session isolée pour l’aperçu.

    Mises à jour optimistes (version) et réservation d’archivage avant appel réseau.
    Les identités et autorisations sont contrôlées côté serveur à chaque écriture.
    """
    def __init__(self, buyers, memory=None, url=''):
        self.buyers = frozenset(str(x) for x in buyers)
        self.memory = memory
        self.url = url
        if memory is None:
            if not url.startswith(('postgresql://','postgres://')):
                raise ValueError('Configurez DATABASE_URL avec une base PostgreSQL persistante avant le mode réel.')
            with self.connection() as db:
                db.execute('''CREATE TABLE IF NOT EXISTS soleol_purchase_orders (
                    id TEXT PRIMARY KEY, owner_id TEXT NOT NULL,
                    version INTEGER NOT NULL, payload TEXT NOT NULL)''')

    @contextmanager
    def connection(self):
        import psycopg
        from psycopg.rows import dict_row
        with psycopg.connect(self.url, connect_timeout=10, row_factory=dict_row) as db:
            yield db

    def is_buyer(self, user):
        return bool(user and str(user.get('id')) in self.buyers)

    def allowed(self, user, order=None, write=False):
        if not user or not user.get('id') or not user.get('name'):
            raise PermissionError('Connexion requise.')
        if write and not self.is_buyer(user):
            raise PermissionError('Seul le département achats peut modifier le suivi.')
        if order and str(user['id']) != order['owner_id'] and not self.is_buyer(user):
            raise PermissionError('Commande inaccessible.')

    def list(self, user):
        self.allowed(user)
        if self.memory is not None:
            values = copy.deepcopy(list(self.memory.values()))
        else:
            with self.connection() as db:
                if self.is_buyer(user):
                    rows = db.execute('SELECT payload FROM soleol_purchase_orders').fetchall()
                else:
                    rows = db.execute('SELECT payload FROM soleol_purchase_orders WHERE owner_id=%s', (str(user['id']),)).fetchall()
                values = [json.loads(row['payload']) for row in rows]
        return sorted([o for o in values if self.is_buyer(user) or o['owner_id']==str(user['id'])], key=lambda o:o['needed'])

    def get(self, oid, user):
        self.allowed(user)
        if self.memory is not None:
            order = copy.deepcopy(self.memory.get(oid))
        else:
            with self.connection() as db:
                row = db.execute('SELECT payload FROM soleol_purchase_orders WHERE id=%s', (oid,)).fetchone()
                order = json.loads(row['payload']) if row else None
        if order is None:
            raise ValueError('Commande introuvable.')
        self.allowed(user, order)
        return order

    def create(self, user, data, request_id):
        self.allowed(user)
        data = validate_request(copy.deepcopy(data))
        data.update(id=request_id, owner_id=str(user['id']), owner_name=user['name'], owner_email=user.get('email',''),
                    status='À traiter', expected='', version=1, archive_state='', archive_task_id='',
                    created=stamp(), events=[event(user, 'Demande transmise pour Stock 530.' if data.get('destination')=='stock530' else 'Demande transmise. Fichier coûts existant : oui.')])
        if self.memory is not None:
            if request_id not in self.memory:
                self.memory[request_id] = data
        else:
            with self.connection() as db:
                db.execute('INSERT INTO soleol_purchase_orders (id,owner_id,version,payload) VALUES (%s,%s,1,%s) ON CONFLICT (id) DO NOTHING',
                           (request_id,str(user['id']),json.dumps(data,ensure_ascii=False)))
        existing = self.get(request_id,user)
        if existing['owner_id'] != str(user['id']):
            raise PermissionError('Identifiant déjà utilisé.')
        return request_id

    def save(self, order, user, version):
        self.allowed(user,order,write=True)
        order = copy.deepcopy(order)
        order['version'] = version + 1
        if self.memory is not None:
            old = self.memory.get(order['id'])
            if not old or old['version'] != version:
                raise Conflict('La commande a été modifiée. Actualisez avant de réessayer.')
            self.memory[order['id']] = order
        else:
            with self.connection() as db:
                cursor = db.execute('UPDATE soleol_purchase_orders SET payload=%s,version=%s WHERE id=%s AND version=%s',
                                    (json.dumps(order,ensure_ascii=False),version+1,order['id'],version))
                if cursor.rowcount != 1:
                    raise Conflict('La commande a été modifiée. Actualisez avant de réessayer.')
        return order

    def update(self, oid, user, version, status, expected, comment):
        order = self.get(oid,user)
        self.allowed(user,order,write=True)
        if order['archive_state']:
            raise ValueError('Une commande archivée ou en cours d’archivage ne peut plus être modifiée.')
        if status not in STATUSES:
            raise ValueError('Statut invalide.')
        if status == 'En cours' and not expected:
            raise ValueError('Indiquez la date de livraison prévue avant de passer en cours.')
        if expected:
            date.fromisoformat(expected)
        if len(comment)>5000:
            raise ValueError('Commentaire trop long.')
        message = f"{order['status']} → {status}. Livraison prévue : {nice(expected)}. {comment}".strip()
        order.update(status=status,expected=expected)
        order['events'].append(event(user,message))
        return self.save(order,user,version)

    def reserve_archive(self, oid, user, version):
        order = self.get(oid,user)
        self.allowed(user,order,write=True)
        if order['status'] != 'Validé' or order['archive_state']:
            raise ValueError('Seule une commande validée non archivée peut être envoyée.')
        order['archive_state'] = 'pending'
        order['events'].append(event(user,'Envoi dans ClickUp demandé.'))
        return self.save(order,user,version)

    def finish_archive(self, oid, user, task_id):
        order = self.get(oid,user)
        if order['archive_state'] not in ('pending','uncertain') or not re.fullmatch(r'[A-Za-z0-9_-]+',task_id):
            raise ValueError('Archivage non confirmé.')
        order['archive_state'] = 'done'
        order['archive_task_id'] = task_id
        order['events'].append(event(user,'Copie dans ClickUp confirmée : '+task_id))
        return self.save(order,user,order['version'])


def archive_description(o):
    lines = [f"SOLEOL-ACHAT:{o['id']}", f"Référence : {'Stock 530' if o.get('destination')=='stock530' else o['prs']}", f"Projet : {o['project']}",
             f"Projet ClickUp : {o['project_task_id']}", f"Objet : {o['title']}",
             f"CDP : {o['owner_name']} — compte {o['owner_id']}", f"E-mail : {o['owner_email']}",
             ('Fichier coûts : sans objet (Stock 530)' if o.get('destination')=='stock530' else 'Fichier coûts existant : oui'), f"Date souhaitée : {nice(o['needed'])}",
             f"Livraison prévue : {nice(o['expected'])}", f"Adresse : {o['address']}",
             f"Priorité : {o['priority']}", 'Statut achats : Validé', '', 'ARTICLES']
    lines += [f"{l['reference'] or 'Référence non renseignée'} | {l['designation']} | {l['quantity']:g} {l['unit']}" for l in o['lines']]
    if o.get('cost_file_url'):
        lines += ['', 'Lien du fichier coûts : '+o['cost_file_url']]
    lines += ['', 'REMARQUES', o['notes'], '', 'HISTORIQUE']
    lines += [f"{e['at']} — {e['actor']} : {e['message']}" for e in o['events']]
    return '\n'.join(lines)


def fresh_user():
    user = current_user(force=True)
    if not user:
        raise AuthError('Reconnectez-vous avant de poursuivre.')
    return user


def token():
    return st.session_state.get('account',{}).get('token','')


def send_archive(store, order):
    if demo_mode():
        st.info('Aperçu : aucun envoi réel. La connexion ClickUp sera activée après configuration.')
        return
    user = fresh_user()
    reserved = store.reserve_archive(order['id'],user,order['version'])
    # Pas de répétition automatique du POST : en cas de coupure, vérifier la copie existante.
    try:
        result = api(f'list/{ARCHIVE_LIST}/task',token(),{
            'name':f"{order['prs']} · {order['project']}", 'description':archive_description(reserved),
            'priority':2 if order['priority']=='Urgente' else 3, 'check_required_custom_fields':True})
        task_id = str(result.get('id',''))
        store.finish_archive(order['id'],user,task_id)
    except Exception:
        st.error('Résultat de l’envoi non confirmé. Cliquez sur « Vérifier dans ClickUp ». Aucun nouvel envoi automatique ne sera effectué.')
        return
    st.session_state['flash'] = 'Commande copiée dans la liste ClickUp et archivée.'
    st.rerun()


def reconcile_archive(store, order):
    user = fresh_user()
    store.allowed(user,order,write=True)
    marker = f"SOLEOL-ACHAT:{order['id']}"
    for task in list_tasks(ARCHIVE_LIST,token()):
        if marker in (task.get('description') or task.get('text_content') or ''):
            store.finish_archive(order['id'],user,str(task['id']))
            st.session_state['flash'] = 'Copie ClickUp retrouvée. Archivage confirmé.'
            st.rerun()
    st.warning('Aucune copie retrouvée. Vérifiez la liste ClickUp et les droits du compte achats avant toute nouvelle tentative. Contactez l’administrateur si l’envoi reste bloqué.')


def demo_orders():
    memory = {}
    store = OrderStore({'demo-chafik'},memory)
    names = ['Chafik Bahbah','Matis Yildizkaya','Jérémie Guillet','Arthur Diss','Ricardo Fernandes']
    for i, (prs,project) in enumerate(DEMO_PROJECTS.items()):
        u = {'id':'demo-chafik' if i==0 else 'demo-'+str(i),'name':names[i]}
        oid = 'exemple-'+str(i)
        store.create(u, {'prs':prs,'project':project,'project_task_id':'demo-'+prs,'title':'Matériel pour le chantier',
            'cost_file':True,'needed':(today()+timedelta(days=5+i)).isoformat(),'priority':'Normale',
            'address':'Dépôt SOLEOL','notes':'Exemple fictif pour découvrir la plateforme.',
            'lines':[{'reference':'SOL-1042','designation':'Connecteurs solaires','quantity':20,'unit':'pce'}]},oid)
        memory[oid]['status'] = STATUSES[min(i//2,2)]
        memory[oid]['expected'] = (today()+timedelta(days=4+i)).isoformat() if i>1 else ''
    return memory



