# Interface identique à l’aperçu HTML, composant bidirectionnel Streamlit.
# Le navigateur ne reçoit jamais les jetons ClickUp ni l’URL PostgreSQL.
import tempfile
import hashlib
from pathlib import Path
import streamlit.components.v1 as components


def preview_order(o):
    return {'id':o['id'],'version':o['version'],'project':o['project'],'ref':'Stock 530' if o.get('destination')=='stock530' else o['prs'],'destination':o.get('destination','project'),
            'title':o['title'],'name':o['owner_name'],'date':o['needed'],
            'delivery':o['address'],'urgent':o['priority']=='Urgente',
            'status':STATUSES.index(o['status']),'expectedDelivery':o['expected'],
            'hasCostFile':o['cost_file'],
            'lines':[[l['designation'],l['quantity'],l['unit'],l['reference']] for l in o['lines']],
            'notes':o['notes'],'history':[e['at']+' · '+e['actor']+' — '+e['message'] for e in o['events']],
            'archiveState':o['archive_state'],'archived':o['archive_state']=='done',
            'archiveTaskId':o['archive_task_id']}


@st.cache_resource
def purchase_component():
    # Même fichier généré à chaque lancement ; aucun fichier supplémentaire à télécharger.
    digest=hashlib.sha256(INTERFACE_HTML.encode()).hexdigest()[:16]
    directory=Path(tempfile.gettempdir())/('soleol_purchase_ui_'+digest)
    directory.mkdir(exist_ok=True)
    (directory/'index.html').write_text(INTERFACE_HTML,encoding='utf-8')
    # Le nom fait partie de l’URL servie au navigateur : une nouvelle interface
    # reçoit une nouvelle URL et ne peut pas réutiliser l’ancien index en cache.
    return components.declare_component('soleol_purchase_ui_'+digest,path=str(directory))


def process_action(action,store,user):
    """Autorise et valide toutes les actions côté Python, y compris en aperçu."""
    kind=action.get('kind')
    p=action.get('payload') or {}
    if not isinstance(p,dict) or len(json.dumps(p))>200000:
        raise ValueError('Demande invalide ou trop volumineuse.')
    if kind=='refresh':
        return {'message':'Données actualisées.'}
    if kind=='search':
        prs=normalize_prs(str(p.get('prs','')))
        projects=find_projects(prs,token())
        st.session_state['verified_search']={'prs':prs,'projects':projects}
        return {'projects':projects}
    if kind in ('confirm_project','create'):
        destination=p.get('destination','project')
        if destination not in ('project','stock530'):
            raise ValueError('Destination de la demande invalide.')
        data={k:p.get(k) for k in ('prs','project_task_id','cost_file','title','needed','priority','address','notes','lines')}
        data['destination']=destination
        if destination=='stock530' and kind=='create':
            if p.get('prs') or p.get('project_task_id'):
                raise ValueError('Stock 530 ne doit pas être associé à un PRS.')
            data.update(prs='',project_task_id='',project='Matériel commun pour le dépôt',cost_file=False,cost_file_url='')
        else:
            search=st.session_state.get('verified_search',{})
            match=next((r for r in search.get('projects',[]) if r['id']==p.get('project_task_id')),None)
            if not match or search.get('prs')!=p.get('prs'):
                raise ValueError('Recherchez puis validez le projet correspondant à ce PRS.')
            if not demo_mode() or match.get('source')=='clickup':
                if not token():
                    raise AuthError('Reconnectez votre compte ClickUp puis recherchez à nouveau le projet.')
                if demo_mode():
                    identity(token())
                task=api('task/'+match['id'],token())
                if task.get('archived') or not project_matches(task,p['prs']):
                    raise ValueError('Le projet a changé dans ClickUp. Recherchez-le à nouveau.')
                link=cost_file_link(task)
                match=dict(match,name=str(task.get('name') or match['name']))
            else:
                link=match.get('cost_file_url','')
            if not link:
                raise ValueError(COST_FILE_BLOCK)
            if kind=='confirm_project':
                return {'project':{'id':match['id'],'name':match['name'],'ref':p['prs']},'message':'Projet validé : lien du fichier coûts présent.'}
            data.update(project=match['name'],cost_file_url=link)
        store.create(user,data,action['id'])
        return {'message':'Votre demande apparaît maintenant dans votre espace, sous « À traiter ».'}
    if kind=='update':
        store.update(str(p.get('id','')),user,int(p.get('version',0)),str(p.get('status','')),
                     str(p.get('expected') or ''),str(p.get('comment') or ''))
        return {'message':'Suivi enregistré. La livraison prévue apparaît sur la carte.'}
    if kind not in ('archive','reconcile'):
        raise ValueError('Action inconnue.')
    oid=str(p.get('id',''))
    order=store.get(oid,user)
    store.allowed(user,order,write=True)
    if demo_mode():
        raise ValueError('Aperçu : aucun envoi réel à ClickUp. Configurez la connexion pour activer l’archivage.')
    if kind=='archive':
        reserved=store.reserve_archive(oid,user,int(p.get('version',0)))
        try:
            result=api(f'list/{ARCHIVE_LIST}/task',token(),{
                'name':f"{'Stock 530' if reserved.get('destination')=='stock530' else reserved['prs']} · {reserved['project']}",
                'description':archive_description(reserved),
                'priority':2 if reserved['priority']=='Urgente' else 3,
                'check_required_custom_fields':True})
            store.finish_archive(oid,user,str(result.get('id','')))
        except Exception:
            raise ValueError('Envoi non confirmé. Ouvrez la commande et utilisez « Vérifier dans ClickUp ». Aucun second envoi automatique ne sera effectué.') from None
    else:
        if order['archive_state'] not in ('pending','uncertain'):
            raise ValueError('Aucun envoi en attente de vérification.')
        marker=f'SOLEOL-ACHAT:{oid}'
        found=next((t for t in list_tasks(ARCHIVE_LIST,token()) if marker in (t.get('description') or t.get('text_content') or '')),None)
        if not found:
            raise ValueError('Aucune copie retrouvée. Faites vérifier les droits et la liste par l’administrateur avant de réinitialiser l’envoi.')
        store.finish_archive(oid,user,str(found['id']))
    return {'message':'Commande copiée dans ClickUp et classée dans les archives.'}


HOST_CSS='''<style>
html,body,.stApp,[data-testid="stAppViewContainer"],[data-testid="stMain"]{background:#101419;color:#edf0f4}
[data-testid="stHeader"]{display:none}
[data-testid="stMainBlockContainer"],.block-container{padding:0!important;max-width:none!important;margin:0!important}
[data-testid="stMainBlockContainer"] [data-testid="stVerticalBlock"]{gap:0}
iframe[title*="soleol_purchase_ui"]{display:block;width:100%;border:0;color-scheme:dark}
[data-testid="stElementContainer"]:has(iframe){margin:0;padding:0}
.st-key-login{max-width:1000px!important;margin:65px auto!important;padding:25px!important;color:#edf0f4}
.st-key-login [data-testid="stMarkdownContainer"]{color:#edf0f4}
.st-key-login a{background:#e0553a;color:white;border:0;border-radius:10px}
</style>'''


def auth_view():
    """Only public login information crosses the component boundary."""
    account=st.session_state.get('account')
    if account and time.time()-account['created']>8*3600:
        st.session_state.pop('account',None);account=None
    if account:
        return {'connected':True,'name':account['user']['name'],'id':account['user']['id']}
    cfg=configuration()
    if not cfg or not ids('CLICKUP_ALLOWED_WORKSPACE_IDS'):
        return {'connected':False,'url':'','message':'Connexion personnelle à configurer par l’administrateur dans les Secrets Streamlit.'}
    if 'pending_auth' not in st.session_state:
        try:
            st.session_state['pending_auth']=relay().creer()
        except ValueError as exc:
            return {'connected':False,'url':'','message':str(exc)}
    state,proof=st.session_state['pending_auth']
    return {'connected':False,'url':'https://app.clickup.com/api?'+urlencode({
        'client_id':cfg['client_id'],'redirect_uri':cfg['redirect_uri'],'state':state}),
        'message':st.session_state.get('auth_message','Connectez-vous pour enregistrer vos demandes sous votre nom.')}


@st.fragment(run_every=2)
def poll_connection():
    pending=st.session_state.get('pending_auth')
    if not pending or st.session_state.get('account'):
        return
    result=relay().recuperer(*pending)
    if result is None:
        return
    st.session_state.pop('pending_auth',None)
    if result.get('token'):
        st.session_state['account']=result
        st.session_state.pop('auth_message',None)
    else:
        st.session_state['auth_message']=result.get('error') or result.get('erreur','Connexion expirée.')
    st.rerun(scope='app')


def main():
    st.set_page_config(page_title='SOLEOL · Achats',page_icon='☀️',layout='wide',initial_sidebar_state='collapsed')
    st.markdown(HOST_CSS,unsafe_allow_html=True)
    callback()
    if demo_mode():
        st.session_state['demo_user']={'id':'demo-preview','name':'Compte aperçu','email':''}
    error=''
    try:
        user=current_user()
    except AuthError as exc:
        error=str(exc);user=None
    auth=auth_view()
    if not auth.get('connected') and auth.get('url'):
        poll_connection()
    store=None;orders=[]
    if user:
        try:
            if demo_mode():
                if 'demo_orders' not in st.session_state:
                    st.session_state['demo_orders']=demo_orders()
                store=OrderStore(buyer_ids(),memory=st.session_state['demo_orders'])
            else:
                store=OrderStore(buyer_ids(),url=setting('DATABASE_URL'))
            orders=store.list(user)
        except ValueError as exc:
            error=str(exc);store=None
        except Exception:
            error='La base de données est indisponible. Faites vérifier DATABASE_URL et les droits de connexion.';store=None
    state={'user':{'name':user['name'] if user else 'Non connecté'},
           'buyer':bool(store and store.is_buyer(user)),'demo':demo_mode(),
           'auth':auth,'searchLive':bool(auth.get('connected')),'searchDemo':demo_mode() and not configuration(),'available':bool(user and store),'error':error,
           'orders':[preview_order(o) for o in orders], 'today':today().isoformat(),
           'defaultDate':(today()+timedelta(days=7)).isoformat()}
    action=purchase_component()(state=state,reply=st.session_state.get('ui_reply'),key='soleol-interface',default=None)
    if not isinstance(action,dict):
        return
    action_id=action.get('id')
    if not isinstance(action_id,str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,100}',action_id):
        return
    done=st.session_state.setdefault('handled_actions',[])
    if action_id in done:
        return
    # Mark before any side effect. On rerun the component's last event is ignored.
    done.append(action_id)
    del done[:-100]
    if action.get('kind')=='logout':
        logout()
    try:
        if not user or not store:
            raise ValueError('Connectez votre compte ClickUp pour accéder aux commandes.')
        response=process_action(action,store,fresh_user())
        reply={'id':action_id,'ok':True,**response}
    except (ValueError,PermissionError) as exc:
        reply={'id':action_id,'ok':False,'message':str(exc)}
    except Exception:
        reply={'id':action_id,'ok':False,'message':'L’opération n’a pas pu être confirmée. Actualisez les données. Pour un envoi ClickUp, vérifiez la copie existante avant toute nouvelle tentative.'}
    st.session_state['ui_reply']=reply
    st.rerun()


if __name__=='__main__':
    main()
